BASE36 = re.compile(rb'[0-9a-z]{64}')
RADICES = (10**21, 2**384, 36**64)
FREQUENCIES = (5, 3, 2)
STARTS = (0, 5, 8)
ALPHABET = b'0123456789abcdefghijklmnopqrstuvwxyz'


