"""Lossless structured-record compression; bzip2 handles other byte streams.

Record values use their natural radices. An integer ANS code interleaves
record tags using probabilities 1/2, 3/10, and 1/5. No corpus is needed to decode.
The stream header includes the record count, final-newline flag and prefix.
"""
import argparse
import bz2
import re
from pathlib import Path

RECORD = re.compile(rb'([A-Za-z0-9_-]+) line (0|[1-9][0-9]{0,5}) ratio 0\.([0-9]{6}) select pick win seed (0|[1-9][0-9]{0,8})')
HEX = re.compile(rb'[0-9a-f]{96}')
BASE36 = re.compile(rb'[0-9a-z]{64}')
HEX_PREFIX = re.compile(rb'[0-9a-f]+')
RADICES = (10**21, 2**384, 36**64)
FREQUENCIES = (5, 3, 2)
STARTS = (0, 5, 8)
ALPHABET = b'0123456789abcdefghijklmnopqrstuvwxyz'


def put_uint(value):
    result = bytearray()
    while value >= 128:
        result.append((value & 127) | 128)
        value >>= 7
    result.append(value)
    return bytes(result)


def get_uint(data, pos):
    value = 0
    for shift in range(0, 70, 7):
        if pos >= len(data):
            raise ValueError('Truncated header')
        byte = data[pos]
        pos += 1
        value |= (byte & 127) << shift
        if byte < 128:
            return value, pos
    raise ValueError('Header integer is too large')


def records(data):
    lines = data.split(b'\n')
    newline = lines[-1] == b''
    if newline:
        lines.pop()
    if not lines or len(lines) >= 2**32:
        return None
    prefix = None
    rows = []
    for line in lines:
        m = RECORD.fullmatch(line)
        if m:
            p, a, r, s = m.groups()
            if prefix is None:
                prefix = p
            if p != prefix:
                return None
            rows.append((0, int(a) * 10**15 + int(r) * 10**9 + int(s)))
        elif HEX.fullmatch(line):
            rows.append((1, int(line, 16)))
        elif BASE36.fullmatch(line):
            rows.append((2, int(line, 36)))
        else:
            return None
    return newline, prefix or b'', rows


def render(kind, value, prefix):
    if kind == 0:
        value, seed = divmod(value, 10**9)
        line, ratio = divmod(value, 10**6)
        return prefix + (b' line %d ratio 0.%06d select pick win seed %d' % (line, ratio, seed))
    if kind == 1:
        return ('%096x' % value).encode('ascii')
    text = bytearray()
    while value:
        value, digit = divmod(value, 36)
        text.append(ALPHABET[digit])
    return bytes(reversed(text)).rjust(64, b'0')


def compress(data):
    fallback = b'B' + bz2.compress(data, compresslevel=9)
    parsed = records(data)
    if parsed is None:
        return fallback
    newline, prefix, rows = parsed
    is_hex = bool(HEX_PREFIX.fullmatch(prefix))
    if is_hex:
        prefix_bytes = bytes.fromhex(('0' if len(prefix) & 1 else '') + prefix.decode('ascii'))
    else:
        prefix_bytes = prefix
    header = (b'S' + put_uint((len(rows) << 1) | newline)
              + put_uint((len(prefix) << 1) | is_hex) + prefix_bytes)
    state = 0
    for kind, value in rows:
        state = state * RADICES[kind] + value
        quotient, remainder = divmod(state, FREQUENCIES[kind])
        state = quotient * 10 + STARTS[kind] + remainder
    packed = header + state.to_bytes((state.bit_length() + 7) // 8, 'big')
